JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('g-kentei-i-q17', '9. AIに関する法律と契約',
   '著作権法が著作物として保護する要件のうち、「創作性」の説明として最も適切なものはどれか。',
   NULL,
   '["世の中でまだ誰も思いついたことがなく、特許のように出願して審査を経て初めて認められるような、真に新しい技術的な発想やしくみであること。", "誰が作ってもほぼ同じ表現になる、ありふれた言い回しや単なる事実の記載には認められない、作者なりの工夫や個性が表現に表れていること。", "書かれている内容がすべて事実に忠実であり、誇張や作り話をまったく含まずに正確に記述されていること。", "制作に費やした時間や金銭的なコストが、他の同種の作品と比べて一定の水準を超えるほど大きくかけられていること。"]',
   1,
   '[1]',
   'single',
   '{"asked": "著作物として保護されるための要件「創作性」が具体的に何を指すかを問う。", "point": "ありふれた表現・単なる事実には創作性が無く、著作物として保護されない。", "why_asked": "創作性を『新しいこと』(特許の新規性)や『手間がかかっていること』と取り違える人が多く、著作権法の一番の入口で差がつくから。", "kid": "誰が書いても同じになるような言い方や、ただの事実の並びには『その人らしさ』が無いので、著作物として守られない。", "eg": "料理のレシピで、材料の分量表そのもの(誰が書いても同じ)は著作物として保護されないが、その分量表を紹介する語り口や文章の書き方には、書いた人なりの工夫(創作性)が表れうる。", "terms": [["創作性", "作者なりの工夫・個性が表現ににじみ出ていること。著作物の要件"], ["著作物", "思想や感情を創作的に表現したもの。単なるデータ・事実の記載は含まない"], ["ありふれた表現", "誰が書いてもほぼ同じになる表現。創作性なしと判断される"]], "think": "著作権法が守っているのは『アイデアそのもの』ではなく『表現』であり、その表現の中でも誰が作っても同じになるものは保護しない。作者ごとの言葉選びや構成の工夫があって初めて、著作物として保護される対象になる。", "vs": "『新しいこと』を求めるのは特許の新規性の話であり、著作権の創作性はあくまで表現に個性が表れているかどうかの話であって、世界初かどうかは問わない。手間や費用の大きさも要件ではない。", "usecase": "AIが生成した文章・画像に著作権が発生するかを考えるとき、まず『表現に工夫があるか』を見る出発点になる。", "opt": ["世の中で初めてかどうかを問うのは特許の新規性の説明であり、著作権法の創作性は表現に個性が表れているかどうかの話であって、新しさそのものを求めるものではない。", "正解。誰が作ってもほぼ同じ表現になるありふれた言い回しや、単なる事実の記載には認められず、作者なりの工夫や個性が表現に表れていることが創作性の中身である。", "事実に忠実であることは創作性とは関係がなく、むしろ単なる事実の記載は創作性が無いとして著作物性が否定されやすい。", "制作にかけた時間や費用の大きさは創作性の要件ではなく、手間をかけただけの作品でも表現に個性がなければ創作性は認められない。"]}'),
  ('g-kentei-i-q18', '9. AIに関する法律と契約',
   'インターネット上に公開されている画像や文章を、AI開発のために使ってよいかどうかを判断する根拠として、最も適切なものはどれか。',
   NULL,
   '["検索エンジンで見つかるデータであれば、二次利用の許諾を得たものとみなしてよい。", "そのデータに付されている利用規約やライセンス契約の内容を確認し、許可された範囲内で使う。", "誰でも閲覧できる状態で公開されていれば、権利者の許可を得なくても自由に使ってよい。", "AI開発への利用は法律で一律に認められているため、個別のデータについて確認する必要はない。"]',
   1,
   '[1]',
   'single',
   '{"asked": "他人のデータやモデルをAI開発に使ってよい根拠が、利用規約・ライセンス契約の確認であることを問う。", "point": "「ネットで見られる」と「自由に使ってよい」は別物。根拠は利用規約・ライセンス契約。", "why_asked": "『公開されている＝自由に使える』という思い込みが根強く、実務でトラブルになりやすい典型パターンだから。", "kid": "お店に並んでいる商品を見られるのと、持ち帰って自由に使ってよいのとは別の話。使ってよい範囲は、商品に貼ってある値札やルール(利用規約・ライセンス)を見て確かめる。", "eg": "図書館の本は誰でも読めるが、コピーしてよい範囲は本の巻末にある利用条件を見て確かめる必要があるのと同じで、ネット上のデータも見られることと使ってよいことは別に確認がいる。", "terms": [["利用規約", "サービスの提供者が定める、そのデータ・サービスの使い方のルール"], ["ライセンス契約", "著作物などの利用を許可する契約。使える範囲や条件を定める"], ["著作権法30条の4", "一定の条件を満たせば著作物を機械学習の訓練データとして許諾なく使えるとする規定(既出)"]], "think": "著作権法30条の4のような法律上の原則があっても、そのデータに個別の利用規約やライセンス契約が付いていて『機械学習への利用を禁じる』と定められていれば、その契約の定めが優先される。だから公開されているかどうかではなく、付随する規約・契約の内容を確認する必要がある。", "vs": "30条の4は『法律が一律に許す範囲』の話、利用規約・ライセンス契約は『個別の権利者が上乗せで制限できる範囲』の話。法律で許されていても契約で禁じられていれば使えない、という順番を混同しない。", "usecase": "外部の画像データセットや学習済みモデルを商用のAI開発に取り込む前に、必ず確認すべきチェック項目。", "opt": ["検索エンジンに表示されることは、単にインデックスされているだけであり、二次利用の許諾が与えられたことにはならない。", "正解。そのデータやモデルに付されている利用規約・ライセンス契約の内容を確認し、許可された範囲内で使うのが基本の判断根拠になる。", "公開されて閲覧できることと、権利者の許可なく複製・利用してよいことは別で、規約やライセンスで制限されていれば自由には使えない。", "AI開発への利用が一律に認められているわけではなく、個別の利用規約やライセンス契約で機械学習への利用が制限されている場合がある。"]}'),
  ('g-kentei-i-q19', '9. AIに関する法律と契約',
   'AIが生成した画像が既存の著作物と似ていた場合に、著作権侵害にあたるかどうかを判断する枠組みとして、最も適切なものはどれか。',
   NULL,
   '["その著作物に接して作られたと言えるかという依拠性と、表現がどれだけ似ているかという類似性の、両方を検討する。", "生成に使われたAIの学習データの中に、その著作物とまったく同じデータが含まれていたかどうかだけで機械的に判断する。", "見た目がどれだけ似ているかという類似性だけを検討すればよく、既存作品を実際に知っていたかどうかまでは問わない。", "既存作品を知っていたかという依拠性だけを検討すればよく、実際の見た目がどれだけ似ているかまでは問わない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "著作権侵害の判断枠組みが、依拠性と類似性の両方を検討するものであることを問う。", "point": "似ているだけでは足りない。「知っていたか(依拠性)」と「似ているか(類似性)」の両方がそろって侵害。", "why_asked": "『似ていれば侵害』という単純化が起きやすく、偶然の一致まで侵害としてしまう誤解を正すために問われる。", "kid": "たまたま似てしまっただけなのか、それとも元の作品を知っていて真似したのかを、両方から確かめる。", "eg": "ある作曲家が誰も聴いたことのないメロディを偶然思いついたら、それが既存の曲に似ていても、その曲を聴いたことがなければ(依拠性が無ければ)著作権侵害にはならない、という考え方に近い。", "terms": [["依拠性", "既存の著作物を知っていた、接していたと言えること"], ["類似性", "表現がどれだけ似ているか"], ["著作権侵害", "依拠性と類似性の両方が認められて初めて成立すると考えられている"]], "think": "表現が似ているだけでは、偶然の一致と真似したものを区別できない。逆に既存作品を知っていただけでも、実際の表現が似ていなければ問題にならない。だから両方の要素をそろえて初めて侵害と判断する枠組みになっている。", "vs": "引用の要件(既出。出所明示や主従関係)は『許諾なく使ってよい例外』の話で、依拠性・類似性は『そもそも侵害と言えるか』を判断する枠組みであり、検討する段階が異なる。", "usecase": "AI生成物が既存作品に似てしまったときに、それが問題になるかどうかを整理して考えるための基本の型。", "opt": ["正解。既存の著作物に接して作られたと言える依拠性と、表現がどれだけ似ているかという類似性の両方を検討して、著作権侵害にあたるかを判断する。", "学習データに著作物が含まれていたかどうかだけでは、生成された表現が実際に似ているかを見ておらず、判断の枠組みとして不十分である。", "類似性だけを見ると、既存作品を知らずに偶然似たものを作ったケースまで侵害としてしまい、判断の枠組みとして不十分である。", "依拠性だけを見ると、既存作品を知っていても実際の表現がまったく似ていないケースまで侵害としてしまい、判断の枠組みとして不十分である。"]}'),
  ('g-kentei-i-q20', '9. AIに関する法律と契約',
   '特許を受けるための要件である「新規性」と「進歩性」の関係の説明として、最も適切なものはどれか。',
   NULL,
   '["新規性と進歩性は同じ内容を指す言葉で、どちらか一方を満たせばもう一方も自動的に満たされる。", "新規性はまだ世の中に知られていないことを、進歩性はその分野の専門家が容易には思いつかないことを、それぞれ求める別の要件である。", "新規性はその分野の専門家が容易には思いつかないことを、進歩性はまだ世の中に知られていないことを、それぞれ求める要件で、名称と中身が逆である。", "新規性は発明者の年齢や所属に関する要件であり、進歩性は発明が完成した年数に関する要件である。"]',
   1,
   '[1]',
   'single',
   '{"asked": "特許の2大要件、新規性と進歩性がそれぞれ何を求める別要件かを問う。", "point": "新規性=まだ知られていない、進歩性=容易に思いつかない。2つの別のハードル。", "why_asked": "新規性と進歩性を同じもののように扱ってしまい、『新しいだけ』で特許が取れると誤解する受験者が多いから。", "kid": "新規性は『まだ誰も見たことがない』かどうか、進歩性は『見た人がすぐ真似できてしまうほど簡単ではない』かどうか、の2つの違うハードル。", "eg": "新しい料理を発表するとき、新規性は『同じ料理がまだ世に出回っていないか』、進歩性は『既にある材料を並べただけで、料理人なら誰でも思いつくレベルではないか』を、それぞれ別に確かめるようなもの。", "terms": [["新規性", "既に世の中に知られていない(公知でない)こと"], ["進歩性", "その分野の専門家(当業者)が容易には思いつかないこと"], ["特許を受ける権利", "発明を完成させた者に発生する、特許出願できる権利"]], "think": "新規性だけを求めると、既存の技術を少し組み合わせただけの誰でも思いつく発明にも特許が与えられてしまう。そこで『専門家が容易に思いつくものではない』という進歩性を別に課すことで、独占を与えるに値する発明だけを保護している。", "vs": "新規性は『既に世に出ているかどうか』という外形的な事実の話、進歩性は『思いつく難しさ』という価値判断の話であり、性質の異なる2つの要件を混同しない。", "usecase": "AIのアルゴリズムに特許性があるかを考えるとき、公知性と発想の難易度の両方を別々にチェックする土台になる。", "opt": ["新規性を満たしても、既存技術の単純な組み合わせのように容易に思いつく発明は進歩性を満たさないことがあり、一方だけで他方が自動的に満たされるわけではない。", "正解。新規性はまだ世の中に知られていないことを、進歩性はその分野の専門家が容易には思いつかないことを、それぞれ別に求める要件である。", "新規性と進歩性の中身が入れ替わっており、正しくは新規性が『まだ知られていないこと』、進歩性が『容易には思いつかないこと』を指す。", "新規性・進歩性はいずれも発明の内容そのものに関する要件であり、発明者の属性や発明にかかった年数を問うものではない。"]}'),
  ('g-kentei-i-q21', '9. AIに関する法律と契約',
   '会社員が業務に関連して行った発明について、特許を受ける権利の発生の仕方として最も適切なものはどれか。著作物の職務著作(既出)との対比で考えよ。',
   NULL,
   '["著作物の職務著作と同じ考え方で、要件を満たせば発明の当初から会社が発明者となり、従業員本人には権利がまったく発生しない。", "発明が完成した時点で自動的に国(特許庁)に権利が帰属してしまい、会社にも従業員にも権利は発生しない。", "原則としてその発明をした従業員本人に発生するが、契約や勤務規則であらかじめ定めておけば、会社に取得させることができる。", "発明した部署の管理職にのみ権利が発生し、実際にその発明をした担当者本人には権利が発生しない。"]',
   2,
   '[2]',
   'single',
   '{"asked": "職務発明で、特許を受ける権利が誰に発生するか(あらかじめの定めの有無で結論が変わること)を、職務著作との対比で問う。", "point": "何も定めがなければ発明は従業員本人に発生する。契約・規則であらかじめ定めておけば、発生した時点から会社に帰属させられる。", "why_asked": "職務著作(定めが無くても要件を満たせば会社)と職務発明(定めが無ければ従業員)とで、『定めが無いときにどちらへ転ぶか』が逆であることを取り違えやすいから。", "kid": "発明そのものをした人は従業員だが、会社があらかじめ『発明が生まれたらうちのものにする』と決めておけば、その発明が生まれたまさにその瞬間から、最初から会社のものとして扱われる。著作物のように必ず最初から会社のもの、というわけではなく、あらかじめの取り決めが要るのがポイント。", "eg": "あらかじめ『生まれた子犬はうちで引き取る』と約束しておくと、生まれた瞬間からその子犬が約束した側のものとして扱われるのに近い。特許を受ける権利も、契約や勤務規則で先に定めておけば、発明が完成した瞬間から会社のものとして原始的に発生し、いったん従業員に渡ってから改めて会社へ譲る、という二段階を踏むわけではない。", "terms": [["職務発明", "従業員が業務に関連して行った発明。特許を受ける権利は原則として従業員本人に発生するが、あらかじめ定めておけば会社に発生させられる"], ["職務著作", "会社の発意で従業員が作成した著作物。要件を満たせば原則として会社が著作者になる(既出)"], ["相当の利益", "あらかじめの定めにより会社が発明の権利を取得する場合に、従業員へ支払われる対価"]], "think": "発明という行為そのものは従業員が行うので、何も定めがなければ権利は従業員本人に発生する。しかし会社があらかじめ契約や勤務規則で『発明が生まれたら会社に取得させる』と定めておけば、特許を受ける権利は発明が完成したその時点から会社に発生する(いったん従業員に発生してから移すのではない)。このとき従業員には相当の利益(対価)を支払う義務が生じる。", "vs": "職務著作は要件を満たせば最初から会社が著作者になる点で職務発明と似ているようで、両者はどちらも『あらかじめの定めがあれば、権利発生の時点から一方の当事者に帰属する』という点で実は共通しており、『まず従業員に発生してから会社に移す』という二段階の仕組みだと誤解しないことが最大のポイント。", "usecase": "AIモデルの開発に関わった従業員が発明をした場合に、権利が誰にどう帰属するかを考える出発点になる。", "opt": ["職務著作は契約・規則に特段の定めが無くても要件を満たせば会社が著作者になるが、職務発明はその逆で、あらかじめ契約・規則で定めておかなければ権利は従業員本人に残る。両者は『定めが無いときにどちらへ転ぶか』が逆であり、同じ考え方ではない。また発明者(自然人)という地位そのものは常に発明をした従業員にあり、会社が発明者になるわけではない。", "発明が完成しただけで国に権利が帰属することはなく、特許を受ける権利はまず発明者である従業員本人に発生する。", "正解。特許を受ける権利は原則としてその発明をした従業員本人に発生し、契約や勤務規則であらかじめ定めておけば会社に取得させることができる。", "権利は実際に発明をした従業員本人に発生するものであり、発明していない管理職に自動的に発生するわけではない。"]}'),
  ('g-kentei-i-q22', '9. AIに関する法律と契約',
   'AIの学習アルゴリズムのようなノウハウを、特許として出願して保護する場合と、営業秘密として秘匿して保護する場合の違いとして、最も適切なものはどれか。',
   NULL,
   '["特許は出願・公開の代わりに一定期間の独占権を得られるが、営業秘密は秘匿し続ける限り期間の制限なく保護されうる代わりに、他社が独自に同じ技術に到達しても対抗できない。", "特許も営業秘密も、いずれも出願を行ったうえで国の審査を受けなければ保護がまったく始まらない点で共通している制度だと考えられる。", "特許は内容をいっさい公開せずに秘匿することで保護され、営業秘密は逆にあらかじめ出願して技術内容を広く公開することによって保護されるという、両者はちょうど逆の関係にある。", "特許も営業秘密も、いずれも技術内容を一切公開せずに秘匿したまま保護される点で共通しており、保護される期間の長さだけが両者で異なっていると考えられる。"]',
   0,
   '[0]',
   'single',
   '{"asked": "AIアルゴリズムのようなノウハウを、特許と営業秘密のどちらで守るかという選択の違いを問う。", "point": "特許=公開して期間限定の独占。営業秘密=隠したまま無期限だが独自開発には無力。", "why_asked": "『特許のほうが強い保護』と単純に思い込みやすく、公開のリスクと秘匿のリスクをそれぞれ理解しているかが問われるから。", "kid": "特許は技術を発表して、その代わりしばらくの間だけ独り占めできる仕組み。営業秘密は技術を隠したままにして、隠し続けている限り誰にも文句を言えるが、他の人が別のやり方で同じものにたどり着いてしまったら止められない。", "eg": "特許はレシピを本にして出版し、その代わり一定期間だけ他の店に真似させない権利をもらう仕組み。営業秘密はレシピを金庫にしまい、誰にも見せない代わりに、他の店が別ルートで同じレシピにたどり着いても文句は言えない仕組み。", "terms": [["特許権", "出願・公開の代わりに、一定期間(出願から20年)独占的に実施できる権利"], ["営業秘密", "秘密として管理し公開しないことで保護される、不正競争防止法上の枠組み"], ["独自開発への対抗", "特許は他社の無断利用そのものを止められるが、営業秘密は他社が独自にたどり着いた同じ技術までは止められない"]], "think": "技術を公開して国のルールで守ってもらうか(特許)、公開せず自分で秘密として守り続けるか(営業秘密)という選択になる。AIの学習ノウハウやパラメータ調整の勘所は、公開すると他社に模倣されやすい割に侵害を外から立証しにくいこともあり、あえて営業秘密として秘匿する選択がされることもある。", "vs": "特許は『公開して独占期間を得る』、営業秘密は『秘匿して無期限に守りうるが独自開発には無力』という、公開の有無と保護の強さがトレードオフになっている点を対にして覚える。", "usecase": "AI開発のノウハウを特許出願するか秘匿するかを検討する場面で、公開のメリット・デメリットを比較する基本の視点。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"12\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">公開して守るか、隠して守るか</text><rect x=\"20\" y=\"26\" width=\"140\" height=\"96\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"90\" y=\"42\" fill=\"#60a5fa\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">特許権</text><text x=\"90\" y=\"60\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">内容を公開する</text><text x=\"90\" y=\"76\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">出願から20年、独占できる</text><text x=\"90\" y=\"92\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">他社の無断利用を止められる</text><text x=\"90\" y=\"110\" fill=\"#c9a04a\" font-size=\"8\" text-anchor=\"middle\">期間が来ると誰でも使える</text><rect x=\"180\" y=\"26\" width=\"140\" height=\"96\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"250\" y=\"42\" fill=\"#6ab08d\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">営業秘密</text><text x=\"250\" y=\"60\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">内容を秘匿し続ける</text><text x=\"250\" y=\"76\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">秘匿できる限り無期限</text><text x=\"250\" y=\"92\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">他社が独自開発したら</text><text x=\"250\" y=\"106\" fill=\"#c9a04a\" font-size=\"8\" text-anchor=\"middle\">対抗できない</text><text x=\"170\" y=\"138\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">レシピを本にして出版する／金庫にしまう、の違い</text></svg>", "opt": ["正解。特許は出願・公開の代わりに一定期間独占できるが、営業秘密は秘匿し続ける限り期間の制限なく保護されうる代わりに、他社が独自に同じ技術へたどり着いても対抗できない。", "営業秘密は国への出願や審査を必要とせず、秘密として管理している事実そのものによって保護される点で特許とは異なる。", "特許は出願の際に内容を公開する制度であり、営業秘密は逆に公開せず秘匿することで保護される制度であって、説明が逆になっている。", "特許は出願時に内容を公開する点で営業秘密とは異なり、両者とも公開しない点で共通するという説明は誤りである。"]}'),
  ('g-kentei-i-q23', '9. AIに関する法律と契約',
   '不正競争防止法上、ある情報が「営業秘密」として保護されるために満たすべき三要件の組み合わせとして、最も適切なものはどれか。',
   NULL,
   '["秘密として管理されていること(秘密管理性)、事業活動に有用であること(有用性)、公然と知られていないこと(非公知性)。", "情報が有償で提供されていること、電子的な形で管理されていること、そして相手が登録済みの会員であることという組み合わせ。", "発明としての新規性、進歩性、そしてあらかじめ特許庁への出願がなされていることという、特許の要件の組み合わせ。", "著作物としての創作性、それが表現されていること、そして著作権者の氏名が明示されていることという組み合わせ。"]',
   0,
   '[0]',
   'single',
   '{"asked": "営業秘密として保護されるための三要件(秘密管理性・有用性・非公知性)の中身を問う。", "point": "秘密管理性・有用性・非公知性の3つがすべてそろって初めて営業秘密。1つでも欠けると保護されない。", "why_asked": "『秘密にしていれば営業秘密になる』と1つの要件だけで済ませてしまいがちだが、三要件がそれぞれ独立していることが問われるから。", "kid": "こっそりしまってある(秘密管理性)、役に立つ(有用性)、他の人がまだ知らない(非公知性)の3つが全部そろって、はじめて『営業秘密』として守ってもらえる。", "eg": "宝物を守るには、金庫に入れて(秘密管理性)、それが本当に価値のあるものであり(有用性)、他の人がまだその存在を知らない(非公知性)という3つの条件が全部そろっている必要がある、というイメージ。", "terms": [["秘密管理性", "アクセス制限やマル秘表示など、秘密として管理されている実態があること"], ["有用性", "事業活動に役立つ、価値のある情報であること"], ["非公知性", "一般に知られていない、公然の情報ではないこと"]], "think": "どれだけ役に立つ情報でも、社内の誰もが自由に見られる状態(秘密管理性を欠く)であれば営業秘密とは認められない。逆に厳重に管理していても、既に業界で広く知られている情報(非公知性を欠く)であれば同じく認められない。3つの要件は独立していて、どれか1つでも欠けると保護されない。", "vs": "有償で会員に提供するデータの保護は、秘密管理性を求めない別枠(限定提供データ、次の設問で扱う)の話であり、営業秘密の三要件とは別の制度である。", "usecase": "AIの学習ノウハウを社内でどう管理すれば営業秘密として保護されうるかを、チェックリストとして確かめるときに使う。", "opt": ["正解。秘密として管理されていること(秘密管理性)、事業活動に有用であること(有用性)、公然と知られていないこと(非公知性)の3つがそろって営業秘密として保護される。", "有償提供・電子的管理・会員登録は、次に扱う限定提供データの制度に近い要素であり、営業秘密の三要件そのものではない。", "新規性・進歩性・出願は特許の要件であり、公開せず秘匿することで保護される営業秘密の要件とは制度そのものが異なる。", "創作性・表現・著作権者の明示は著作物に関する要件であり、技術情報などを秘匿によって保護する営業秘密の要件ではない。"]}'),
  ('g-kentei-i-q24', '9. AIに関する法律と契約',
   '会員向けに有償で提供している気象データのように、特定の相手には見せるが自社の外には秘密にしていない情報を、不正な取得・使用から保護する不正競争防止法上の枠組みとして、最も適切なものはどれか。',
   NULL,
   '["営業秘密として扱うべきものであり、秘密管理性・有用性・非公知性という三要件のすべてを満たさなければならないという枠組み。", "特許権として扱うべきものであり、技術的な発明について出願・審査の手続きを経て初めて与えられる独占的な権利という枠組み。", "編集著作物として扱うべきものであり、データの選択や配列そのものに創作性が認められる場合にのみ保護されるという枠組み。", "限定提供データ。秘密管理性までは求めず、電子的に管理され業として特定の者に反復して提供されているデータを保護する枠組み。"]',
   3,
   '[3]',
   'single',
   '{"asked": "会員に有償提供するデータを保護する枠組み、限定提供データが営業秘密とは別枠であることを問う。", "point": "「特定の相手には見せる」データは秘密管理性を満たさないので、営業秘密でなく限定提供データで守る。", "why_asked": "会員向けデータの保護をそのまま営業秘密の話だと思い込みやすく、秘密管理性を満たすかどうかの区別が問われるから。", "kid": "誰にも見せない宝物(営業秘密)と、お金を払った人にだけ見せる商品(限定提供データ)は、守り方のルールが別。", "eg": "非公開の秘伝のタレ(営業秘密)と、会員だけに販売する限定メニューの詳しいレシピ(限定提供データ)は、どちらも大事に扱うが、守るための法律上の仕組みは別になっている、というイメージ。", "terms": [["限定提供データ", "特定の者に業として反復して提供する、電子的に管理されたデータを保護する不正競争防止法上の枠組み"], ["秘密管理性", "営業秘密で必須の要件。限定提供データでは求められない"]], "think": "会員に売っているデータは、社外の会員には見せている時点で『秘密』ではなく、営業秘密の秘密管理性を満たさない。そこで、秘密管理性を求めない別枠の制度として限定提供データが設けられ、電子的な管理と特定の者への反復提供という実態を根拠に保護する。", "vs": "営業秘密は『誰にも見せない』ことが前提、限定提供データは『特定の相手には見せる(売る)』ことが前提。守りたいデータの性質(誰にも見せないか、お金をもらって見せるか)に応じて使い分ける。", "usecase": "会員制のデータ提供ビジネスで、不正コピーや無断転売からデータを守るための法的な根拠として使われる。", "opt": ["特定の会員には見せている時点で、社外に対しては秘密にしていないため秘密管理性を満たさず、営業秘密の三要件をそのまま適用することはできない。", "特許権は出願・審査を経て与えられる技術的発明の権利であり、有償提供されているデータそのものを保護する制度ではない。", "編集著作物として保護されるにはデータの選択・配列そのものに創作性が必要で、単に有償で提供しているだけでは編集著作物の保護は及ばない。", "正解。秘密管理性までは求めず、電子的に管理され業として特定の者に反復して提供されているデータを保護する、限定提供データの枠組みにあたる。"]}'),
  ('g-kentei-i-q25', '9. AIに関する法律と契約',
   'AIやビッグデータをめぐる独占禁止法上の懸念として、近年具体的に指摘されている論点として、最も適切なものはどれか。',
   NULL,
   '["AIが新たに生成した文章や画像について、そもそも創作性が認められて著作物として保護されるのかどうかという、著作権法上の論点。", "AIモデル開発を進めるための契約において、成果物として新たに生まれた知的財産権がどちらの当事者に帰属することになるのかという、契約条項上の論点。", "AIモデルの学習にすでに使われた既存の著作物について、その権利者へ利用料の支払いが必要かどうかという、著作権法上の論点。", "大量のデータを持つ事業者がデータを囲い込んで新規参入を妨げることや、複数の事業者の価格設定アルゴリズムが結果として協調的な価格形成を招くこと。"]',
   3,
   '[3]',
   'single',
   '{"asked": "独占禁止法がAIに関して具体的にどんな論点で問題視されているかを問う。", "point": "独禁法の関心は「競争が守られているか」。データの囲い込みと、アルゴリズム同士の協調的な値上がりが典型例。", "why_asked": "巨大IT企業の規制を漠然と『独占禁止法』とだけ覚えると、他の法律(著作権法など)の論点と混ざってしまうため、具体的な中身まで区別できるかが問われるから。", "kid": "独占禁止法は『競争がちゃんと成り立っているか』を見張る法律。データを1社が抱え込んでしまうことや、値段を決めるAI同士が示し合わせたわけでもないのに結果的に足並みをそろえてしまうことが心配されている。", "eg": "町の駄菓子屋が全部同じチェーン店になってしまい値段の選びようがなくなる状態(データの囲い込み)や、各店のレジのAIが互いの値段を見ながら自動で値上げし続け、話し合っていないのに結果的に値段がそろってしまう状態(アルゴリズムによる協調)が、独占禁止法の心配ごとに近い。", "terms": [["データの囲い込み", "大量データを1社が独占し、他社の参入や競争を妨げる状態"], ["アルゴリズムによる協調的な価格形成", "各社が独立に価格設定アルゴリズムを使った結果、話し合いなしに価格が足並みをそろえてしまう現象"]], "think": "独占禁止法はもともと『企業同士が話し合って値段を決める(カルテル)』を禁じてきたが、AIの価格設定アルゴリズムどうしが互いの動きに反応し合ううちに、話し合っていなくても結果的に価格が協調してしまう新しいパターンが近年の論点になっている。", "vs": "知的財産の帰属や利用料の支払い、生成物の創作性は、それぞれ契約実務や著作権法の論点であり、『市場の競争を守る』という独占禁止法の関心とは軸が異なる。", "usecase": "プラットフォーマーのデータ独占や、価格設定アルゴリズムの設計を検討する際に意識すべき規制の観点。", "opt": ["生成物に創作性が認められるかは著作権法上の論点であり、独占禁止法が扱う市場競争の観点とは別である。", "知的財産権の帰属は開発契約で定める条項上の論点であり、市場での競争を守る独占禁止法の論点そのものではない。", "学習データの利用料の支払いは著作権法上の論点であり、独占禁止法が扱う『競争が守られているか』という観点とは別である。", "正解。データを持つ事業者がデータを囲い込んで新規参入を妨げることや、価格設定アルゴリズムどうしが結果的に協調してしまうことが、AIに関する独占禁止法上の論点として指摘されている。"]}'),
  ('g-kentei-i-q26', '9. AIに関する法律と契約',
   '複数の企業がAI開発の共同検討を始める最初の段階で、開発内容の詳細を相手に開示する前に取り交わされることが多い契約として、最も適切なものはどれか。',
   NULL,
   '["保守契約。納品が終わった後のシステムの不具合対応や定期点検について定める契約。", "ライセンス契約。既存のデータや技術をどの範囲まで利用してよいか条件を定める契約。", "NDA(秘密保持契約)。開示する情報の範囲や目的外使用の禁止、有効期間などを定める。", "請負契約。開発する成果物の完成を約束し、完成しなければ報酬を受け取れないことを定める契約。"]',
   2,
   '[2]',
   'single',
   '{"asked": "AI開発の検討段階で最初に結ばれる契約、NDA(秘密保持契約)の役割を問う。", "point": "開発本体の契約より前、まだ何も決まっていない検討段階でNDAを結ぶ。", "why_asked": "NDAを『開発契約の一部』だと思い込みやすく、開発が始まる前の段階で先に結ぶものだという順番が問われるから。", "kid": "商談の前に『ここで聞いた話は他の人に言いません』という約束を先に交わしておくのがNDA。", "eg": "お見合いの前に『今日話したことは他言しません』とお互い約束してから、初めて詳しい話を切り出すようなもの。AI開発でも、詳しい話を切り出す前にまずこの約束を交わす。", "terms": [["NDA(Non-Disclosure Agreement＝秘密保持契約)", "検討段階で開示する情報を秘密として扱う約束を定める契約"], ["目的外使用の禁止", "開示された秘密情報を、合意した目的以外に使わないという約束"]], "think": "AI開発の検討段階では、どんなデータを持っているか、どんな課題を抱えているかといった機微な情報を相手に見せる必要がある。開発本体の契約(請負・準委任)を結ぶかどうかもまだ分からない段階で、まずNDAを結び、開示した情報が外部に漏れたり目的外に使われたりしないようにする。", "vs": "請負・準委任は『開発そのもの』を進めるための契約、保守は『納品後』の契約であり、NDAはそれらより前、検討段階の入口で結ばれる点が最大の違い。", "usecase": "他社に自社のデータや課題感を見せて共同検討を始めるとき、最初に確認・締結すべき契約として実務でよく登場する。", "opt": ["保守契約は納品後の運用段階で結ばれる契約であり、開発の検討段階よりずっと後のタイミングで登場する。", "ライセンス契約は既存のデータや技術の利用条件を定める契約であり、これから何を検討するかを話し合う入口の段階に結ぶものとは性質が異なる。", "正解。検討段階で情報を開示する前に、開示する情報の範囲や目的外使用の禁止、有効期間などを定めるNDA(秘密保持契約)が取り交わされることが多い。", "請負契約は成果物の完成を約束する開発本体の契約であり、まだ何も決まっていない検討段階の最初に結ぶものではない。"]}'),
  ('g-kentei-i-q27', '9. AIに関する法律と契約',
   '精度を事前に約束することが難しいAIモデルの開発フェーズで、契約類型として準委任契約が選ばれやすい理由として、最も適切なものはどれか。',
   NULL,
   '["準委任契約は書面を作らず口頭の合意だけで足りるとされており、契約書を作成する手間がかからない契約類型だからという理由。", "準委任契約は成果物の完成そのものを約束する契約であり、AI開発であっても精度の達成を確実に保証できるからという理由。", "準委任契約は仕事の完成を約束する必要がなく、決められた業務を注意深く遂行すれば足りるため、精度を保証しにくいAI開発の性質に合うから。", "準委任契約は請負契約と比べて、開発を担当する側が受け取れる報酬の金額をあらかじめより高く設定できる契約類型だから選ばれやすいという理由。"]',
   2,
   '[2]',
   'single',
   '{"asked": "精度を約束しにくいAI開発で準委任契約が選ばれやすい理由(完成義務の有無)を問う。", "point": "準委任は「完成」でなく「注意深くやったか」を約束する。精度を保証できないAI開発に合う。", "why_asked": "請負と準委任の違いを『金額』や『書面の有無』のような枝葉の点と誤解しやすく、『完成を約束するかどうか』という本質を問うため。", "kid": "準委任は『真剣に取り組みます』という約束で、『必ずこの精度を出します』という約束ではない。だから、やってみないと精度が分からないAI開発に向いている。", "eg": "請負は『完成した家を引き渡して初めて代金をもらう』工務店の契約、準委任は『決められた時間、誠実に相談に乗る』顧問弁護士の契約に近い。AI開発のPoCや追加学習の段階は、あらかじめ完成の姿(精度)を約束できないため、後者の考え方に近くなる。", "terms": [["請負契約", "仕事の完成を約束し、完成しなければ原則として報酬を受け取れない契約"], ["準委任契約", "一定の事務処理を任せ、注意深く(善良な管理者としての注意をもって)遂行すれば足りる契約"]], "think": "AI開発は、実際にデータを学習させてみるまでどれくらいの精度が出るか分からないという特性を持つ。完成(一定の精度)を最初から約束させる請負契約では、この不確実性を開発者側が一方的に背負うことになりやすい。そこで『決められた業務を注意深く行えば足りる』準委任契約が、探索的な段階では選ばれやすい。", "vs": "『完成を約束するかどうか』が請負と準委任の分かれ目であり、報酬の高さや書面の要否とは無関係。要件が固まった後の開発フェーズでは請負が選ばれることもあり、フェーズに応じて使い分けられる。", "usecase": "AI開発をアセスメント・PoC・開発・追加学習といった段階に分けて契約する際に、各段階でどちらの契約類型が向くかを判断する視点になる。", "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"12\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">完成を約束するか、しないか</text><rect x=\"20\" y=\"26\" width=\"140\" height=\"92\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"90\" y=\"42\" fill=\"#60a5fa\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">請負契約</text><text x=\"90\" y=\"60\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">仕事の完成を約束する</text><text x=\"90\" y=\"78\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">完成しないと</text><text x=\"90\" y=\"92\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">報酬を受け取れない</text><rect x=\"180\" y=\"26\" width=\"140\" height=\"92\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"250\" y=\"42\" fill=\"#6ab08d\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">準委任契約</text><text x=\"250\" y=\"60\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">注意深く遂行すれば足りる</text><text x=\"250\" y=\"78\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">完成(精度)そのものは</text><text x=\"250\" y=\"92\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">約束しない</text><text x=\"170\" y=\"133\" fill=\"#c9a04a\" font-size=\"8.5\" text-anchor=\"middle\">精度を事前に約束できないAI開発は準委任型が選ばれやすい</text></svg>", "opt": ["書面の作成が不要かどうかは契約類型の実務上の慣行の話であり、準委任契約が選ばれる理由である完成義務の有無とは別の論点である。", "成果物の完成を約束するのは準委任ではなく請負契約であり、準委任契約はそもそも完成そのものを約束しない契約類型である。", "正解。準委任契約は仕事の完成を約束する必要がなく、決められた業務を注意深く遂行すれば足りるため、精度を事前に保証しにくいAI開発の段階に合う。", "契約類型の選択は完成義務の有無で決まるものであり、報酬の高さは請負と準委任のどちらを選ぶかを決める理由ではない。"]}'),
  ('g-kentei-i-q28', '9. AIに関する法律と契約',
   'AIモデルを納品して終わりにするのではなく、運用開始後もモデルの精度劣化を監視し、必要に応じて再学習を行う体制を契約であらかじめ定めておく理由として、最も適切なものはどれか。',
   NULL,
   '["AIモデルの保守は著作権法上の義務としてすでに定められており、契約の有無にかかわらず開発者が無償で行う必要があるから。", "保守契約さえあらかじめ結んでおけば、開発時点ですでに生じていた精度不足の責任を発注者側にすべて転嫁できるようになるから。", "モデルというものは一度学習を終えてしまえば、その後は運用中に精度が変化することは基本的になく、保守契約はあくまで形式的に結んでおくだけの契約にすぎないから。", "運用開始後にデータの傾向が変化してモデルの精度が徐々に落ちていくことがあるため、劣化への対応を誰がいつどこまで担うのかを明確にしておく必要があるから。"]',
   3,
   '[3]',
   'single',
   '{"asked": "納品後の精度劣化に備えて保守契約を結ぶ理由を問う。", "point": "AIは運用中も傾向がずれて劣化する。誰がいつ何を担うかを契約で先に決めておく。", "why_asked": "『納品して終わり』という通常のソフトウェアのイメージのままAI開発の契約を考えると、劣化への対応主体が曖昧なまま運用に入ってしまうから。", "kid": "AIモデルは作った後も、世の中の傾向が変わるとだんだん見立てがずれていく。誰がそれに気づいて直すのかを、あらかじめ約束しておく契約。", "eg": "車を買った後、乗りっぱなしにせず車検や点検を受けるように、AIモデルも納品後に定期的な点検(監視)と部品交換(再学習)が必要で、その役割分担を保守契約で先に決めておく、というイメージ。", "terms": [["保守契約", "納品後の運用段階における、点検・不具合対応・再学習などの役割分担を定める契約"], ["精度劣化", "運用中にデータの傾向が変わり、以前は正確だったモデルの精度が落ちていく現象"]], "think": "通常のソフトウェアと違い、AIモデルは世の中の変化に合わせてデータの傾向がずれ、放っておくと精度が落ちていく。誰が精度を監視し、誰が再学習の費用を負担するかを、納品前の契約段階で決めておかないと、劣化に気づいても対応する主体が曖昧なままになってしまう。", "vs": "請負・準委任は『開発フェーズ』の契約であるのに対し、保守契約は『運用フェーズ』の契約という、対象とする時期の違いを区別する。", "usecase": "AIモデルを本番導入した後、長期的に精度を維持していくための体制づくりに直結する契約実務。", "opt": ["AIモデルの保守が著作権法上の義務として無償で定められているという事実はなく、保守の内容・費用負担は契約で個別に取り決める。", "保守契約は運用段階での役割分担を定めるものであり、開発時点の精度不足の責任を運用段階の契約で発注者側に転嫁できる仕組みではない。", "AIモデルは運用中のデータの傾向変化によって精度が落ちていくことがあり、保守契約は精度劣化への実際の対応を定める実務上重要な契約である。", "正解。運用開始後にデータの傾向が変化してモデルの精度が徐々に落ちていくことがあるため、その監視・対応を誰がいつどこまで担うのかを保守契約であらかじめ明確にしておく。"]}'),
  ('g-kentei-i-q29', '9. AIに関する法律と契約',
   'クラウド上でAI機能を提供するSaaS型サービスの利用規約で、特に確認が必要とされる事項として、最も適切なものはどれか。',
   NULL,
   '["利用者がそのサービスへ加入した日付そのものを、提供者が外部に公表してよいかどうかという条項の確認。", "利用者が入力したデータを、サービス提供者がモデルの学習・改善にも使ってよいことになっていないか、というデータの利用権に関する条項。", "サービスを提供するためのサーバーが設置されている場所が、国内なのか国外なのかという条項だけを確認すればよい。", "サービスの画面デザインなど見た目の部分についての著作権が、利用者側と提供者側のうちのどちらに帰属することになるのかという条項の確認。"]',
   1,
   '[1]',
   'single',
   '{"asked": "SaaS型AIサービスの利用規約で確認すべき、入力データの利用権に関する条項を問う。", "point": "SaaS型では「入力したデータが学習に使われないか」の条項が急所。", "why_asked": "SaaS型サービスの特殊性を『精度保証』の話だけで済ませてしまいがちだが、日々入力するデータの扱いという別の急所が問われるから。", "kid": "AIサービスに毎日打ち込んでいる自社のデータが、知らないうちにそのAIをもっと賢くするための勉強材料に使われていないか、規約を見て確かめる必要がある。", "eg": "チェーン店の相談窓口で話した内容が、そのまま他の支店の接客マニュアルの材料に使われてしまわないか気になるのと同じで、SaaS型AIに入力したデータがそのまま他社のためにもモデルの学習材料として使われていないかを確かめる、というイメージ。", "terms": [["SaaS(Software as a Service)", "ソフトウェアをインストールせず、クラウド上のサービスとして利用する提供形態"], ["データ利用権", "利用者が入力したデータを、提供者が学習等に利用してよい範囲を定める条項"]], "think": "SaaS型AIサービスでは、利用者が日々の業務で入力するデータそのものが、サービス改善やモデルの学習に使われることがある。自社の業務データが他の利用者にも使われるモデルの学習に流用されないかは、利用規約のデータ利用権の条項を見ないと分からない。", "vs": "既出の『AIサービス提供契約での精度保証の考え方』とは別の論点で、こちらは『入力したデータが誰の手でどう使われるか』という利用権に焦点を当てる。", "usecase": "業務データをSaaS型AIサービスに入力する前に、利用規約の中でも特に確認すべきチェックポイントとして使われる。", "opt": ["加入日の公表可否は付随的な事項であり、SaaS型AIサービスの特殊性として特に確認が必要とされる入力データの利用権の問題ではない。", "正解。利用者が入力したデータを、サービス提供者がモデルの学習・改善にも使ってよいことになっていないかというデータ利用権の条項は、SaaS型AIサービスで特に確認が必要になる。", "サーバーの設置場所だけを見ても、日々入力しているデータが学習に使われるかどうかという利用権の問題は分からない。", "画面デザインの著作権の帰属は一般的なウェブサービスでも問題になりうる項目だが、SaaS型AIサービスに特有の急所である入力データの扱いとは焦点が異なる。"]}'),
  ('g-kentei-i-q30', '9. AIに関する法律と契約',
   '経済産業省が策定した「AI・データの利用に関する契約ガイドライン」の位置づけとして、最も適切なものはどれか。',
   NULL,
   '["契約の考え方を示す指針であり、法律のような強制力(罰則)を持たないソフトローにあたる。", "国会での審議を経て可決・成立した法律であり、違反すると罰則が科されるハードローにあたる。", "裁判所が個別の裁判の中で示した、AI開発契約に関する判例をまとめた資料である。", "特定の業界団体が加盟企業だけに強制している、内部規則としての契約書のひな形集にすぎない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "「AI・データの利用に関する契約ガイドライン」が、罰則を伴わないソフトローであることを問う。", "point": "このガイドラインは経産省の「指針」であり、法律(ハードロー)ではない。従わなくても罰則はない。", "why_asked": "ガイドラインという名前から法律のように強制力があると誤解しやすく、ソフトローとハードローの違いを理解しているかが問われるから。", "kid": "『こう考えるとうまくいきますよ』という、国のおすすめ集のようなもの。守らなくても罰は受けないが、契約でもめないための参考になる。", "eg": "料理番組が教えるおすすめの下ごしらえの手順のようなもので、従わなくても罰金は取られないが、従うとトラブルなく美味しく作りやすい、というイメージ。", "terms": [["AI・データの利用に関する契約ガイドライン", "経済産業省が策定した、AI開発・データ利用の契約実務の考え方を示す指針"], ["ソフトロー", "法律のような罰則を伴う強制力を持たない、指針・ガイドラインの類"], ["ハードロー", "罰則を伴う強制力のある法律"]], "think": "このガイドラインは、探索的段階型(アセスメント→PoC→開発→追加学習)の契約の考え方などを示しているが、あくまで『考え方の指針』であり、これに従わなくても罰則を受けるわけではない。実務では参考にされつつも、法律のような強制力は持たない。", "vs": "法律(ハードロー)は違反すると罰則があるのに対し、ガイドライン(ソフトロー)は違反しても罰則がなく、あくまで実務の参考として尊重される、という強制力の有無を対にして覚える。", "usecase": "AI開発契約を結ぶ実務担当者が、契約書の設計や交渉の考え方を検討する際に参照する代表的な指針。", "opt": ["正解。契約の考え方を示す指針であり、法律のような強制力(罰則)を持たないソフトローにあたる。従わなくても罰則を受けることはない。", "国会で可決・成立した法律ではなく、経済産業省が実務の考え方を示すために策定した指針であり、罰則を伴うハードローではない。", "個別の裁判の判決をまとめた判例集ではなく、契約実務の考え方をあらかじめ整理して示した指針である。", "業界団体ではなく国の省庁である経済産業省が策定したものであり、特定の業界団体の加盟企業だけを対象とした内部規則ではない。"]}')
) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei-i'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
